```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;

  // Open SQLite connection to test_db.sqlite
  auto conn_res = sqlite::Connection::create("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // Drop Product table if it exists
  {
    auto res = conn.execute(
        "DROP TABLE IF EXISTS Product");
    if (!res) {
      return false;
    }
  }

  // Create Product table with the required schema
  {
    const char* create_sql =
        "CREATE TABLE Product ("
        "product_id INTEGER PRIMARY KEY, "
        "name VARCHAR(100) NOT NULL, "
        "price REAL NOT NULL, "
        "category VARCHAR(50) NOT NULL, "
        "stock INTEGER NOT NULL DEFAULT 0"
        ")";
    auto res = conn.execute(create_sql);
    if (!res) {
      return false;
    }
  }

  // Begin transaction
  {
    auto res = conn.execute("BEGIN TRANSACTION");
    if (!res) {
      return false;
    }
  }

  // Perform batch insert using sqlgen
  {
    auto insert_res = conn.insert<Product>(products);
    if (!insert_res) {
      // Rollback on failure
      conn.execute("ROLLBACK");
      return false;
    }
  }

  // Commit transaction
  {
    auto res = conn.execute("COMMIT");
    if (!res) {
      return false;
    }
  }

  return true;
}

}  // namespace batch_insert_products
```

