namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

/**
 * This function deletes inactive users from the "User" table in the "test_db.sqlite" database.
 * Inactive users are defined as those who have not logged in since 2025-01-01.
 * Returns: bool.
 */
bool delete_inactive_users() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  try {
    // 1. Connect to the SQLite database "test_db.sqlite"
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // 2. Use a transaction to ensure safety
    conn.begin_transaction();

    // 3. Delete users who have not logged in since 2025-01-01
    // SQL equivalent:
    // DELETE FROM User
    // WHERE last_login < DATE('2025-01-01');
    const auto query =
        delete_from<User> | where("last_login"_c < sqlgen::DateTime{"2025-01-01"});

    conn.execute(query);

    // 4. Commit the transaction
    const bool committed = conn.commit_transaction();

    // 5. Return operation result of commit
    return committed;
  } catch (...) {
    // In case of any failure, indicate the operation did not succeed.
    return false;
  }
}

} // namespace delete_inactive_users
