struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

/**
 * Description: This function returns a list of active users who have posted within
 *              2025-12-01 and 2025-12-31 (inclusive).
 * Returns: std::vector<ActiveUser>.
 */
std::vector<ActiveUser> query_active_users_posts() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlite::Connection::make("test_db.sqlite");
  if (!conn_res.ok()) {
    return {};
  }
  auto conn = conn_res.value();

  // Create User and Post tables if they don't exist
  {
    const std::string create_user_sql =
        "CREATE TABLE IF NOT EXISTS `User` ("
        "  `user_id` INTEGER PRIMARY KEY,"
        "  `username` VARCHAR(50) NOT NULL"
        ");";
    conn->exec(create_user_sql).value();
  }

  {
    const std::string create_post_sql =
        "CREATE TABLE IF NOT EXISTS `Post` ("
        "  `post_id` INTEGER PRIMARY KEY,"
        "  `user_id` INTEGER,"
        "  `created_at` DATETIME NOT NULL,"
        "  FOREIGN KEY(`user_id`) REFERENCES `User`(`user_id`)"
        ");";
    conn->exec(create_post_sql).value();
  }

  // Build the query:
  // SELECT DISTINCT u.user_id, u.username
  // FROM User u
  // INNER JOIN Post p ON u.user_id = p.user_id
  // WHERE p.created_at >= '2025-12-01'
  //   AND p.created_at <= '2025-12-31';
  const auto query =
      read<std::vector<ActiveUser>> |
      from<User, Post>() |
      where("User.user_id"_c == "Post.user_id"_c &&
            "Post.created_at"_c >= sqlgen::DateTime("2025-12-01") &&
            "Post.created_at"_c <= sqlgen::DateTime("2025-12-31")) |
      distinct();

  auto result = query(conn);
  if (!result.ok()) {
    return {};
  }

  return result.value();
}

}  // namespace query_active_users_posts
