#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_customer_purchase_history {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
  std::string email;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  sqlgen::ForeignKey<int, Customer, "customer_id"> customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};

/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto result_conn = sqlite::Connection::connect("test_db.sqlite");
  if (!result_conn) {
    return {};
  }
  const auto& conn = *result_conn;

  // Build the query equivalent to:
  // SELECT p.name, o.order_date, oi.quantity
  // FROM Customer c
  // JOIN "Order" o ON c.customer_id = o.customer_id
  // JOIN OrderItem oi ON o.order_id = oi.order_id
  // JOIN Product p ON oi.product_id = p.product_id
  // WHERE c.customer_id = ?
  // ORDER BY o.order_date DESC;
  const auto query =
      read<std::vector<PurchaseHistory>> |
      from<Customer, Order, OrderItem, Product>() |
      select(Product::name, Order::order_date, OrderItem::quantity) |
      where(Customer::customer_id == customer_id) |
      join<Order>(Order::customer_id == Customer::customer_id) |
      join<OrderItem>(OrderItem::order_id == Order::order_id) |
      join<Product>(OrderItem::product_id == Product::product_id) |
      order_by(desc(Order::order_date));

  auto res = query(conn);
  if (!res) {
    return {};
  }
  return *res;
}

}  // namespace query_customer_purchase_history
