#include <vector>

namespace query_daily_traffic_metrics {

struct PageVisit {
  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Open SQLite connection to the given database file.
  auto conn_res = sqlite::Connection::open("test_db.sqlite");
  if (!conn_res) {
    throw std::runtime_error(conn_res.error().message());
  }
  auto conn = std::move(conn_res).value();

  // Build the query equivalent to:
  //
  // SELECT strftime('%Y-%m-%d', visit_time) AS visit_date,
  //        COUNT(*) AS total_visits,
  //        COUNT(DISTINCT url) AS unique_pages
  // FROM PageVisit
  // GROUP BY visit_date
  // ORDER BY visit_date;
  //
  // using sqlgen's dynamic query builder.
  auto query = dynamic::SelectFrom{
      .fields =
          {
              dynamic::SelectFrom::Field{
                  .val = dynamic::Operation{dynamic::Function{
                      .name = "strftime",
                      .args = {dynamic::ColumnOrValue{"%Y-%m-%d"},
                               dynamic::ColumnOrValue{
                                   dynamic::Column{"PageVisit", "visit_time"}}}}},
                  .as = std::optional<std::string>("visit_date")},
              dynamic::SelectFrom::Field{
                  .val = dynamic::Operation{dynamic::Aggregation{
                      .type = dynamic::AggregationType::COUNT,
                      .arg = std::optional<dynamic::ColumnOrValue>(
                          dynamic::ColumnOrValue{
                              dynamic::Column{"PageVisit", "*"}}),
                      .distinct = false}},
                  .as = std::optional<std::string>("total_visits")},
              dynamic::SelectFrom::Field{
                  .val = dynamic::Operation{dynamic::Aggregation{
                      .type = dynamic::AggregationType::COUNT,
                      .arg = std::optional<dynamic::ColumnOrValue>(
                          dynamic::ColumnOrValue{
                              dynamic::Column{"PageVisit", "url"}}),
                      .distinct = true}},
                  .as = std::optional<std::string>("unique_pages")},
          },
      .table_or_query =
          dynamic::SelectFrom::TableOrQueryType{
              dynamic::Table{.name = "PageVisit"}},
      .joins = {},
      .where = std::nullopt,
      .group_by = dynamic::GroupBy{
          .columns = {dynamic::Column{"", "visit_date"}}},
      .order_by = dynamic::OrderBy{
          .columns = {dynamic::OrderBy::Column{
              .column = dynamic::Column{"", "visit_date"},
              .direction = dynamic::OrderDirection::ASC}}},
      .limit = std::nullopt};

  // Execute the query and collect results.
  auto range_res =
      select_from<DailyTraffic>(conn, Ref<dynamic::SelectFrom>(query));

  if (!range_res) {
    throw std::runtime_error(range_res.error().message());
  }

  auto range = std::move(range_res).value();

  std::vector<DailyTraffic> result;
  for (const auto& row : range) {
    result.push_back(row);
  }

  return result;
}

}  // namespace query_daily_traffic_metrics
