#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Start with a base SELECT query
  auto query = sqlgen::read<std::vector<Book>>;

  // Dynamically add WHERE clauses based on provided filters

  if (filters.title_keyword.has_value()) {
    // Use LIKE for title search, e.g., '%keyword%'
    const auto pattern = "%" + *filters.title_keyword + "%";
    query = query | where("title"_c.like(pattern));
  }

  if (filters.min_year.has_value()) {
    // year >= min_year
    query = query | where("year"_c >= *filters.min_year);
  }

  if (filters.genre.has_value()) {
    // genre = ?
    query = query | where("genre"_c == *filters.genre);
  }

  if (filters.max_price.has_value()) {
    // price <= max_price
    query = query | where("price"_c <= *filters.max_price);
  }

  // Execute the query and unwrap the result
  auto result = query(conn);

  if (!result) {
    // On error, return empty vector; in a real system you might throw or log
    return {};
  }

  return *result;
}

}  // namespace query_search_books_by_criteria
