#pragma once

#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_create_trigger_audit_log {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct AuditLog {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> log_id;
  std::string table_name;
  int record_id;
  std::string action;
  sqlgen::DateTime timestamp;
};

/**
 * Function: Create a trigger for auditing changes on Product table.
 * @return true if trigger creation succeeds, false otherwise
 */
bool create_trigger_audit_log() {
  // Open (or create) SQLite database "test_db.sqlite".
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // Ensure Product and AuditLog tables exist, using sqlgen to create them.
  // If table creation fails for any reason, return false.
  auto res =
      sqlgen::sqlite::create_table<Product>(conn).and_then([&](const auto&) {
        return sqlgen::sqlite::create_table<AuditLog>(conn);
      });

  if (!res) {
    return false;
  }

  // Raw SQL for the trigger, as requested.
  const std::string trigger_sql =
      "CREATE TRIGGER IF NOT EXISTS audit_product_update\n"
      "AFTER UPDATE ON Product\n"
      "BEGIN\n"
      "    INSERT INTO AuditLog (table_name, record_id, action, timestamp)\n"
      "    VALUES ('Product', OLD.product_id, 'UPDATE', CURRENT_TIMESTAMP);\n"
      "END;";

  // Execute the trigger creation SQL.
  auto trig_res = sqlgen::exec(conn, trigger_sql);
  if (!trig_res) {
    return false;
  }

  return true;
}

}  // namespace schema_create_trigger_audit_log
