#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // SQL statements for adding columns
  const std::string add_phone_sql =
      "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);";
  const std::string add_is_active_sql =
      "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;";

  // Helper lambda to execute a statement and treat "duplicate column" as success
  auto exec_ignore_duplicate_column =
      [&conn](const std::string& sql) -> bool {
        auto res = sqlgen::exec(conn, sql);
        if (res) {
          return true;
        }

        // Check if error is due to column already existing.
        // SQLite error for duplicate column is "duplicate column name: <name>"
        // We don't have direct typed errors here, so we inspect the message.
        std::string msg = res.error().message;
        // Be permissive and just check for "duplicate column name"
        if (msg.find("duplicate column name") != std::string::npos) {
          return true;
        }
        return false;
      };

  if (!exec_ignore_duplicate_column(add_phone_sql)) {
    return false;
  }
  if (!exec_ignore_duplicate_column(add_is_active_sql)) {
    return false;
  }

  return true;
}

}  // namespace schema_migration_add_column
