```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  if (ids.empty()) {
    return true;  // Nothing to delete, consider this a success.
  }

  // Build: update<Document> | set("is_deleted"_c = 1, "deleted_at"_c = CURRENT_TIMESTAMP)
  //                      | where("doc_id"_c.in(ids));
  const auto query =
      update<Document> |
      set("is_deleted"_c = 1,
          "deleted_at"_c = functions::current_timestamp()) |
      where("doc_id"_c.in(ids));

  // Connect to the SQLite database "test_db.sqlite" and execute the query.
  auto result = sqlite::connect("test_db.sqlite")
                    .and_then(query);

  return result.has_value();
}

}  // namespace soft_delete_records
```

