#include <sqlgen/where.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // Begin transaction
  if (!conn->begin_transaction()) {
    return false;
  }

  // 1) Load the source account and check balance
  Account from_acc_template;
  from_acc_template.account_id = from_account_id;

  auto from_res = read<Account>(*conn, from_acc_template);
  if (!from_res || from_res->empty()) {
    conn->rollback();
    return false;
  }

  const auto& from_acc = from_res->front();
  if (from_acc.balance < amount) {
    conn->rollback();
    return false;
  }

  // 2) Update from_account: balance = balance - amount
  {
    dynamic::Update upd_from =
        update<Account>()
            .set(&Account::balance, Account::balance - amount)
            .where(&Account::account_id == from_account_id);

    auto exec_res = conn->execute(sqlite::to_sql(upd_from));
    if (!exec_res) {
      conn->rollback();
      return false;
    }
  }

  // 3) Update to_account: balance = balance + amount
  {
    dynamic::Update upd_to =
        update<Account>()
            .set(&Account::balance, Account::balance + amount)
            .where(&Account::account_id == to_account_id);

    auto exec_res = conn->execute(sqlite::to_sql(upd_to));
    if (!exec_res) {
      conn->rollback();
      return false;
    }
  }

  // Commit transaction
  if (!conn->commit()) {
    conn->rollback();
    return false;
  }

  return true;
}

}  // namespace transaction_transfer_funds
