#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <sqlgen/sqlite/connect.hpp>
#include <string>

namespace upsert_user_profile {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

/**
 * @brief Insert or update a user profile in the database.
 *
 * Uses SQLite's INSERT OR REPLACE semantics. Since user_id is the PRIMARY KEY,
 * this will:
 *   - insert a new row if user_id does not exist
 *   - replace the existing row if user_id already exists
 *
 * @param u The user profile to insert or update.
 * @return true If the operation is successful.
 * @return false If the operation fails.
 */
bool upsert_user_profile(const UserProfile& u) {
  try {
    using namespace sqlgen;

    // Connect to SQLite database "test_db.sqlite"
    auto conn_res = sqlite::connect("test_db.sqlite");
    if (!conn_res) {
      return false;
    }
    auto& conn = *conn_res;

    // Use the generic insert API, which for SQLite will generate an
    // "INSERT OR REPLACE" statement for a struct with a PrimaryKey.
    auto res = insert(conn, u);
    return static_cast<bool>(res);
  } catch (...) {
    return false;
  }
}

} // namespace upsert_user_profile
