```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  // Mark this as a view; sqlgen uses this to know it shouldn't try to CREATE TABLE.
  static constexpr bool is_view = true;
  // Optional explicit view name, otherwise sqlgen will derive it from the type name.
  static constexpr const char* viewname = "SalesSummary";

  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * @return A vector of SalesSummary structs
 */
std::vector<SalesSummary> create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the existing SQLite database file "test_db.sqlite".
  // Assuming default options; adjust if the project provides a specific API.
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Ensure tables exist (no-op if already created).
  conn.create_table_if_not_exists<Product>();
  conn.create_table_if_not_exists<Sale>();

  // Build the SELECT used for the view.
  // SQL equivalent:
  // SELECT p.name AS product_name,
  //        SUM(s.quantity) AS total_quantity,
  //        SUM(s.amount)   AS total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name;
  const auto query =
      select(Product{}.name.as("product_name"),
             sum(Sale{}.quantity).as("total_quantity"),
             sum(Sale{}.amount).as("total_revenue"))
          .from(Sale{}, Product{})
          .where(Sale{}.product_id == Product{}.product_id)
          .group_by(Product{}.name);

  // Create or replace the view `SalesSummary` using the query above.
  conn.create_view_as<SalesSummary>(query);

  // Select from the view and materialize the results into a vector of structs.
  return conn.template select_from<SalesSummary>().to_vector();
}

}  // namespace schema_create_view_sales_summary
