```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::string department_name;
  std::optional<std::string> project_name;
};

/**
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * Returns: std::vector<DepProj>, where each struct contains the department name (if available) and the project name.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Open SQLite connection to the given database.
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // We want RIGHT JOIN of Project to Department:
  //   SELECT Department.name, Project.name
  //   FROM Project
  //   RIGHT JOIN Department ON Project.department_id = Department.department_id;
  //
  // sqlgen provides LEFT JOIN, FULL JOIN, etc. For a RIGHT JOIN, we can simply
  // perform a LEFT JOIN with the table order swapped:
  //   Department LEFT JOIN Project ON Department.department_id = Project.department_id;
  //
  // This guarantees all departments are present, optionally with a project.

  using Dep = Department;
  using Proj = Project;

  // Build the left join expression:
  auto join = sqlgen::select<Dep, Proj>()
                  .from<Dep>()
                  .left_join<Proj>(
                      sqlgen::on(&Dep::department_id, &Proj::department_id));

  // Execute the query and collect the results as pairs of optional rows.
  const auto res = conn.read(join);

  std::vector<DepProj> out;
  out.reserve(res.size());

  for (const auto& row : res) {
    const auto& dep_opt  = std::get<0>(row);
    const auto& proj_opt = std::get<1>(row);

    // For a left join starting from Department, department should always exist.
    // But we still guard defensively.
    if (!dep_opt.has_value()) {
      continue;
    }

    DepProj dp;
    dp.department_name = dep_opt->name;

    if (proj_opt.has_value()) {
      dp.project_name = proj_opt->name;
    } else {
      dp.project_name = std::nullopt;
    }

    out.emplace_back(std::move(dp));
  }

  return out;
}

}  // namespace right_join_departments_projects
