#include <vector>
#include <optional>
#include <cstdint>
#include <string>

namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

std::vector<TemporalAnalysis> analyze_temporal_data() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // Connect to the existing SQLite database "test_db.sqlite".
  auto conn_result = connect("test_db.sqlite");
  if (!conn_result) {
    // On failure, just return an empty result.
    return {};
  }
  auto conn = *conn_result;

  // The SQL functions used here:
  //  - strftime('%d', ...), '%m', '%Y', '%H', '%M', '%S'
  //  - strftime('%w', ...) for weekday (0-6, Sunday = 0)
  //  - strftime('%s', ...) for Unix epoch
  //  - julianday(...) to compute day differences
  //
  // We will build the equivalent of:
  //
  // SELECT
  //   event_id,
  //   event_name,
  //   CAST(strftime('%d', start_time) AS INTEGER) AS start_day,
  //   CAST(strftime('%m', start_time) AS INTEGER) AS start_month,
  //   CAST(strftime('%Y', start_time) AS INTEGER) AS start_year,
