#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 * Returns: true if the item is inserted, false if the item is already in the table.
 */
bool upsert_inventory_items(Inventory item) {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // If connection fails, treat as failure to insert; here we just return false.
    return false;
  }
  auto conn = std::move(conn_res).value();

  // Attempt to insert the item without OR REPLACE first.
  // If this succeeds, the row was newly inserted.
  auto insert_res = insert(conn, item);
  if (insert_res) {
    return true;  // inserted
  }

  // If we get here, the insert failed (likely due to PRIMARY KEY conflict),
  // so we perform an upsert (INSERT OR REPLACE).
  (void)insert_or_replace(conn, item);

  // Since the record already existed and was replaced, return false.
  return false;
}

}  // namespace upsert_inventory_items
