#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <string>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze who and whom are friends in the social network.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl() {
  // Open SQLite connection
  auto conn_res = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_res) {
    // On failure, just return empty result (could also throw in real code).
    return {};
  }
  auto conn = *conn_res;

  // Define minimal structs mapping the existing DB tables.
  // These names must match the actual table/column names in the DB.
  struct DbUser {
    int user_id;
    std::string username;
  };

  struct DbFriendship {
    int user_id1;
    int user_id2;
    std::string friendship_date;
  };

  using sqlgen::col;
  using sqlgen::from;
  using sqlgen::inner_join;
  using sqlgen::select;

  // We want to reproduce the reference SQL:
  //
  // SELECT u1.username, u2.username
  // FROM Friendship f
  // JOIN User u1 ON f.user_id1 = u1.user_id
  // JOIN User u2 ON f.user_id2 = u2.user_id;
  //
  // With sqlgen we build the statement compositionally.
  auto stmt =
      select(col<DbUser>("username"), col<DbUser>("username"))
          .from(
              from<DbFriendship>() |
              inner_join<DbUser>(
                  // First join: Friendship.user_id1 = User.user_id
                  col<DbFriendship>("user_id1"),
                  col<DbUser>("user_id")) |
              inner_join<DbUser>(
                  // Second join: Friendship.user_id2 = User.user_id
                  col<DbFriendship>("user_id2"),
                  col<DbUser>("user_id")));

  // Execute query and collect results as a vector of rows.
  // Each row is a vector<optional<string>>; we expect exactly two columns:
  // u1.username and u2.username.
  auto exec_res = conn->exec(stmt);
  if (!exec_res) {
    return {};
  }

  std::vector<FriendConnection> result;

  for (const auto& row : *exec_res) {
    if (row.size() < 2) {
      continue;
    }

    FriendConnection fc;
    fc.user1_name = row[0].value_or("");
    fc.user2_name = row[1].value_or("");

    result.emplace_back(std::move(fc));
  }

  return result;
}

}  // namespace analyze_social_network
