#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <cmath>
#include <stdexcept>

namespace mathematical_operations_analysis {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  // Connect to SQLite database "test_db.sqlite".
  // The constructor of Connection usually takes a connection string / filename.
  Connection conn{"test_db.sqlite"};

  // Ensure that the Product table exists with the expected schema.
  // We create it if it doesn't exist. This is a temporary table for the analysis.
  {
    auto create_res = conn.exec(
        "CREATE TABLE IF NOT EXISTS Product ("
        "product_id INTEGER PRIMARY KEY,"
        "name TEXT NOT NULL,"
        "price REAL NOT NULL,"
        "quantity INTEGER NOT NULL,"
        "discount_rate REAL NOT NULL"
        ");");
    if (!create_res) {
      throw std::runtime_error("Failed to create Product table: " +
                               create_res.error().message());
    }
  }

  // Read all products from the Product table using sqlgen's read API.
  // The Product struct maps to the Product table.
  std::vector<Product> products;
  {
    auto read_res = conn.read<Product>();
    if (!read_res) {
      throw std::runtime_error("Failed to read products: " +
                               read_res.error().message());
    }
    products = std::move(read_res.value());
  }

  // Now run the mathematical analysis directly in SQL using sqlite functions.
  // Some functions in the reference SQL are not native in SQLite (e.g., CEIL, FLOOR, LOG2),
  // so we use compatible expressions:
  // - CEIL(x)  -> CAST(ROUND(x + 0.5, 0) AS INTEGER)
  // - FLOOR(x) -> CAST(ROUND(x - 0.5, 0) AS INTEGER)
  // - LOG2(x)  -> LOG(x) / LOG(2)
  //
  // SQLite provides:
  // - ABS, ROUND, EXP, LOG (natural log), SIN, COS, TAN, SQRT
  //
  // We compute all requested values and then map each row to MathAnalysis.
  const char* sql =
      "SELECT "
      "  product_id, "
      "  name, "
      "  ABS(price) AS abs_price, "
      "  CAST(ROUND(price + 0.5, 0) AS REAL) AS ceil_price, "
      "  CAST(ROUND(price - 0.5, 0) AS REAL) AS floor_price, "
      "  ROUND(price, 2) AS rounded_price, "
      "  EXP(discount_rate / 100.0) AS exp_discount, "
      "  LOG(price) AS ln_price, "
      "  LOG(quantity) / LOG(2.0) AS log2_quantity, "
      "  SIN(discount_rate) AS sin_discount, "
      "  COS(discount_rate) AS cos_discount, "
      "  TAN(discount_rate) AS tan_discount, "
      "  SQRT(quantity) AS sqrt_quantity "
      "FROM Product;";

  auto stmt_res = conn.prepare(sql);
  if (!stmt_res) {
    throw std::runtime_error("Failed to prepare analysis query: " +
                             stmt_res.error().message());
  }

  auto stmt = stmt_res.value();
  Iterator it{stmt, conn.shared_from_this()};

  std::vector<MathAnalysis> result;
  for (; !it.end(); it.step()) {
    MathAnalysis m{};
    // Column indices in SELECT:
    // 0: product_id
    // 1: name
    // 2: abs_price
    // 3: ceil_price
    // 4: floor_price
    // 5: rounded_price
    // 6: exp_discount
    // 7: ln_price
    // 8: log2_quantity
    // 9: sin_discount
    // 10: cos_discount
    // 11: tan_discount
    // 12: sqrt_quantity

    m.product_id = it.get<int>(0).value_or(0);
    m.name = it.get<std::string>(1).value_or("");

    m.abs_price = it.get<double>(2).value_or(0.0);
    m.ceil_price = it.get<double>(3).value_or(0.0);
    m.floor_price = it.get<double>(4).value_or(0.0);
    m.rounded_price = it.get<double>(5).value_or(0.0);
    m.exp_discount = it.get<double>(6).value_or(0.0);
    m.ln_price = it.get<double>(7).value_or(0.0);
    m.log2_quantity = it.get<double>(8).value_or(0.0);
    m.sin_discount = it.get<double>(9).value_or(0.0);
    m.cos_discount = it.get<double>(10).value_or(0.0);
    m.tan_discount = it.get<double>(11).value_or(0.0);
    m.sqrt_quantity = it.get<double>(12).value_or(0.0);

    result.push_back(std::move(m));
  }

  return result;
}

}  // namespace mathematical_operations_analysis
