#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <algorithm>
#include <cctype>

namespace trim_and_length_validation {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  std::string email;
};

struct ValidatedProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string trimmed_name;
  std::string trimmed_email;
  int name_length;
  int email_length;
};

namespace detail {

// Helper to trim whitespace from both ends of a string.
inline std::string trim(const std::string& s) {
  auto begin = std::find_if_not(s.begin(), s.end(),
                                [](unsigned char ch) { return std::isspace(ch); });
  auto end = std::find_if_not(s.rbegin(), s.rend(),
                              [](unsigned char ch) { return std::isspace(ch); })
                 .base();
  if (begin >= end) {
    return std::string{};
  }
  return std::string(begin, end);
}

}  // namespace detail

/**
 * This function demonstrates how to trim whitespace from string columns
 * and validate their lengths using sqlgen read API.
 * Returns: std::vector<ValidatedProfile>, where each struct contains the
 * user_id, trimmed_name, trimmed_email, name_length, and email_length.
 */
std::vector<ValidatedProfile> trim_and_length_validation() {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  const auto result =
      sqlite::connect("test_db.sqlite")
          // Read all UserProfile rows
          .and_then(sqlgen::read<std::vector<UserProfile>>);

  // If there was an error, return an empty vector.
  if (!result) {
    return {};
  }

  const auto& profiles = *result;
  std::vector<ValidatedProfile> validated;
  validated.reserve(profiles.size());

  for (const auto& p : profiles) {
    ValidatedProfile vp;
    vp.user_id = p.user_id;

    vp.trimmed_name = detail::trim(p.name);
    vp.trimmed_email = detail::trim(p.email);

    vp.name_length = static_cast<int>(vp.trimmed_name.size());
    vp.email_length = static_cast<int>(vp.trimmed_email.size());

    validated.push_back(std::move(vp));
  }

  return validated;
}

}  // namespace trim_and_length_validation
