namespace calculate_order_metrics {

using namespace sqlgen;
using namespace sqlgen::sqlite;

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by querying the OrderItem table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl() {
  // Open SQLite connection to the provided database.
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // If connection fails, return empty vector (or could throw in other designs).
    return {};
  }
  auto conn = std::move(conn_result).value();

  using namespace sqlgen::literals;

  // Build a SELECT statement using sqlgen that mirrors the reference SQL:
  //
  // SELECT
  //   item_id,
  //   order_id,
  //   product_id,
  //   unit_price,
  //   quantity,
  //   discount_rate,
  //   tax_rate,
  //   (unit_price * quantity) as gross_total,
  //   (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)) as discounted_total,
  //   (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100) *
  //     (1 + COALESCE(tax_rate, 0)/100)) as final_total,
  //   (unit_price * quantity / quantity) as unit_cost,
  //   (quantity % 10) as quantity_group,
  //   (unit_price * 0.3) as estimated_profit
  // FROM OrderItem;
  //
  // We emit the metrics in one query and map directly into OrderMetrics.
  //
  // The sqlgen DSL uses column literals like "unit_price"_c, arithmetic,
  // and .as<"alias">() for named projection that maps into struct fields.

  // Helper expressions with explicit COALESCE for nullable discount/tax.
  const auto unit_price_col = "unit_price"_c;
  const auto quantity_col = "quantity"_c;
  const auto discount_col = "discount_rate"_c;
  const auto tax_col = "tax_rate"_c;

  // COALESCE(discount_rate, 0)
  const auto discount_nonnull = coalesce(discount_col, 0.0);
  // COALESCE(tax_rate, 0)
  const auto tax_nonnull = coalesce(tax_col, 0.0);

  // gross_total = unit_price * quantity
  const auto gross_total_expr = (unit_price_col * quantity_col).as<"gross_total">();

  // discounted_total = unit_price * quantity * (1 - discount_nonnull / 100)
  const auto discounted_total_expr =
      (unit_price_col * quantity_col *
       (1.0 - discount_nonnull / 100.0))
          .as<"discounted_total">();

  // final_total =
  //   unit_price * quantity *
  //   (1 - discount_nonnull / 100) *
  //   (1 + tax_nonnull / 100)
  const auto final_total_expr =
      (unit_price_col * quantity_col *
       (1.0 - discount_nonnull / 100.0) *
       (1.0 + tax_nonnull / 100.0))
          .as<"final_total">();

  // unit_cost = unit_price * quantity / quantity
  const auto unit_cost_expr =
      (unit_price_col * quantity_col / quantity_col).as<"unit_cost">();

  // quantity_group = quantity % 10
  const auto quantity_group_expr = (quantity_col % 10).as<"quantity_group">();

  // estimated_profit = unit_price * 0.3
  const auto estimated_profit_expr =
      (unit_price_col * 0.3).as<"estimated_profit">();

  // The basic columns we also want in the result.
  const auto base_query =
      select_from<OrderItem>(
          "item_id"_c, "order_id"_c, "product_id"_c, unit_price_col,
          quantity_col,
          // For nullable input columns, map to non-nullable doubles in the
          // result by coalescing to 0.0.
          discount_nonnull.as<"discount_rate">(),
          tax_nonnull.as<"tax_rate">(),
          gross_total_expr, discounted_total_expr, final_total_expr,
          unit_cost_expr, quantity_group_expr, estimated_profit_expr) |
      to<OrderMetrics>;

  // Execute query and return results (or empty on error).
  auto result = conn.and_then(base_query);
  if (!result) {
    return {};
  }
  return std::move(result).value();
}

}  // namespace calculate_order_metrics
