 * It returns the matched row from the Customer table.
 * Returns: Customer.
 */
Customer read_single_record_by_id(int id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error(
        std::string("Failed to connect to SQLite database: ") +
        conn_result.error().message());
  }
  auto conn = std::move(conn_result.value());

  // Build a read query that fetches a single Customer by primary key
  const auto query =
      sqlgen::read<std::vector<Customer>> |
      sqlgen::where(col<&Customer::customer_id>() == id);

  // Execute the query
  auto result = conn.exec(query);
  if (!result) {
    throw std::runtime_error(
        std::string("Failed to execute read query: ") +
        result.error().message());
  }

  auto customers = std::move(result.value());

  // Expect exactly one matching row; handle not found or multiple rows
  if (customers.empty()) {
    throw std::runtime_error("No Customer found with the given id");
  }
  if (customers.size() > 1) {
    throw std::runtime_error("More than one Customer found with the given id");
  }

  return customers.front();
}

}  // namespace read_single_record_by_id
