 */
std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  std::vector<UpdatedNote> result;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = Connection::make("test_db.sqlite");
  if (!conn_res.is_ok()) {
    // If connection fails, just return empty vector.
    return result;
  }
  auto conn = conn_res.value();

  // Begin transaction
  if (!conn->begin_transaction().is_ok()) {
    return result;
  }

  // Select all notes
  auto select_res = select_from<Note>(*conn);
  if (!select_res.is_ok()) {
    conn->commit();  // best effort to close transaction
    return result;
  }

  auto notes = select_res.value();

  // Process each note: replace "foo" with "bar" and update DB
  for (auto& note : notes) {
    const std::string& original = note.content;
    std::string updated = original;

    // Replace all occurrences of "foo" with "bar"
    const std::string from = "foo";
    const std::string to = "bar";

    std::string::size_type pos = 0;
    bool changed = false;
    while ((pos = updated.find(from, pos)) != std::string::npos) {
      updated.replace(pos, from.size(), to);
      pos += to.size();
      changed = true;
    }

    if (!changed) {
      // No update needed, but still add to result with original content
      result.push_back(UpdatedNote{note.note_id, original});
      continue;
    }

    // Update the note in the database using sqlgen update API
    // We update only the content column for the row with the given primary key.
    Note updated_note{note.note_id, updated};

    auto update_res = update(*conn, updated_note);
    if (!update_res.is_ok()) {
      // If an update fails, skip this row; continue with others.
      continue;
    }

    result.push_back(UpdatedNote{note.note_id, updated});
  }

  // Commit transaction
  conn->commit();

  return result;
}

}  // namespace replace_text_in_notes

