};

/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::Connection::make("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.unwrap();

  // Drop the Inventory table if it exists, then recreate it.
  {
    // DROP TABLE IF EXISTS Inventory;
    const auto drop_stmt =
        dynamic::Statement::from_sql("DROP TABLE IF EXISTS `Inventory`");
    if (!conn->execute(drop_stmt)) {
      return false;
    }

    // CREATE TABLE Inventory (
    //   item_id    INTEGER PRIMARY KEY,
    //   name       VARCHAR(100) NOT NULL,
    //   quantity   INTEGER NOT NULL,
    //   location   VARCHAR(50)
    // );
    const auto create_stmt = dynamic::Statement::from_sql(
        "CREATE TABLE `Inventory` ("
        "`item_id` INTEGER PRIMARY KEY,"
        "`name` VARCHAR(100) NOT NULL,"
        "`quantity` INTEGER NOT NULL,"
        "`location` VARCHAR(50))");
    if (!conn->execute(create_stmt)) {
      return false;
    }
  }

  // Begin transaction for bulk insert
  if (!conn->begin_transaction()) {
    return false;
  }

  // Bulk write: INSERT INTO Inventory(...) VALUES ...
  {
    // Build a static write statement for Inventory
    const auto write_stmt = write(items);

    // Execute the write on the SQLite connection
    if (!conn->insert(write_stmt)) {
      // Rollback on failure (best-effort; ignore result)
      conn->rollback();
      return false;
    }
  }

  // Commit the transaction
  if (!conn->commit()) {
    return false;
  }

  // Read back items with quantity > 50 ordered by quantity DESC
  {
    const auto query =
        read<std::vector<Inventory>> |
        where("quantity"_c > 50) |
        order_by(desc("quantity"_c));

    auto res = conn->select(query);
    if (!res) {
      return false;
    }

    const auto& fetched = res.unwrap();
    return !fetched.empty();
  }
}

}  // namespace inventory_bulk_write_and_read
