```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the given SQLite database file
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = std::move(conn_res.value());

  // Build the operation pipeline:
  // 1. Drop Child and Parent tables if they exist
  // 2. Enable foreign keys and set cascade rules
  // 3. Create Parent and Child tables
  // 4. Insert a Parent row and a corresponding Child row
  // 5. Delete the Parent and verify that the Child is deleted
  auto result =
      conn.and_then(drop<Child> | if_exists)
