namespace column_is_null_checks {

struct Profile {
  sqlgen::PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Open/attach to SQLite database "test_db.sqlite"
  auto db = sqlgen::sqlite::Database{"test_db.sqlite"};

  // Read all profiles into memory
  const auto profiles = db.exec(
      sqlgen::read<std::vector<Profile>> |
      where("bio"_c.is_null() or "avatar_url"_c.is_null()));

  // Transform to Result (profile_id, display_name)
  std::vector<Result> results;
  results.reserve(profiles.size());
  for (const auto& p : profiles) {
    results.push_back(Result{.profile_id = p.profile_id, .display_name = p.display_name});
  }

  return results;
}

}  // namespace column_is_null_checks
