#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * sets the balance and status of an Account identified by acc_id.
 * @param acc_id: The id of Account to be updated.
 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  // Create connection to SQLite database "test_db.sqlite".
  auto conn_res = sqlgen::sqlite::Connection::make("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // Create the Account table.
  {
    auto create_res =
        sqlgen::create_table<Account>(*conn).if_not_exists().exec();
    if (!create_res) {
      return false;
    }
  }

  // Insert a row if it does not exist so that we can update it.
  {
    auto rows_res =
        sqlgen::select_from<Account>(*conn)
            .where([](const auto& a) { return a.account_id == 0; })
            .exec();
    if (!rows_res) {
      return false;
    }

    const auto& rows = *rows_res;
    const bool has_row = std::any_of(rows.begin(), rows.end(),
                                     [acc_id](const Account& a) {
                                       return a.account_id == acc_id;
                                     });

    if (!has_row) {
      Account a{sqlgen::PrimaryKey<int>{acc_id}, 0.0, "inactive"};
      auto ins_res = sqlgen::insert(a).into<Account>(*conn).exec();
      if (!ins_res) {
        return false;
      }
    }
  }

  // Perform update using set(...) for balance and status.
  {
    double new_balance = 1000.0;
    std::string new_status = "active";

    auto upd_res =
        sqlgen::update<Account>(*conn)
            .set([](auto& a) {
              // Values will be supplied via with_values below.
              a.balance = 0.0;
              a.status = "";
            })
            .with_values([&](auto& a) {
              a.balance = new_balance;
              a.status = new_status;
            })
            .where([&](const auto& a) { return a.account_id == acc_id; })
            .exec();

    if (!upd_res) {
      return false;
    }
  }

  // Verify that the changes persisted.
  {
    auto rows_res =
        sqlgen::select_from<Account>(*conn)
            .where([&](const auto& a) { return a.account_id == acc_id; })
            .exec();
    if (!rows_res) {
      return false;
    }

    const auto& rows = *rows_res;
    if (rows.empty()) {
      return false;
    }

    const auto& a = rows.front();
    if (a.balance != 1000.0 || a.status != "active") {
      return false;
    }
  }

  return true;
}

}  // namespace update_set_operations
