#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  using namespace sqlgen;

  // Open SQLite connection to the given database file.
  sqlite::Connection conn{"test_db.sqlite"};

  // Build the FULL JOIN:
  // SELECT Supplier.name AS supplier_name, Product.name AS product_name
  // FROM Supplier
  // FULL JOIN Product ON Supplier.supplier_id = Product.supplier_id;
  //
  // Note: In this schema, we want to keep suppliers without products and
  // products without suppliers. We also allow product_name to be null.
  const auto query =
      select(
          Supplier::name.as<"supplier_name">(),
          Product::name.as<"product_name">())
          .from<Supplier>()
          .full_join<Product<"p">>(
              Supplier::supplier_id == Product::supplier_id);

  // Execute the query and collect the results into SupProd structs.
  // The library maps NULL to std::optional<std::string> automatically.
  auto result = conn.select<SupProd>(query);

  // If execution failed, return an empty vector.
  if (!result) {
    return {};
  }

  return *result;
}

}  // namespace full_join_suppliers_products
