```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <tuple>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees() {
  using namespace sqlgen;

  // Connect to the provided SQLite database.
  auto db = sqlite::Database("test_db.sqlite");

  // Make sure ORM knows about our tables.
  db.register_table<Department>("Departments");
  db.register_table<Employee>("Employees");

  JoinAnalysis analysis;

  // Helper lambda to convert a query row into JoinResult.
  auto row_to_join_result =
      [](const std::tuple<std::optional<std::string>,
                          std::optional<std::string>,
                          std::optional<std::string>,
                          std::optional<double>>& row) -> JoinResult {
        JoinResult jr;
        jr.department_name = std::get<0>(row);
        jr.first_name = std::get<1>(row);
        jr.last_name = std::get<2>(row);
        jr.salary = std::get<3>(row);
        return jr;
      };

  // INNER JOIN: employees with assigned departments
  {
    const auto rows = db.query<std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<double>>(
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Departments d "
        "INNER JOIN Employees e ON d.department_id = e.department_id;");

    for (const auto& r : rows) {
      analysis.inner_join_results.push_back(row_to_join_result(r));
    }
  }

  // LEFT JOIN: all employees (even without departments)
  {
    const auto rows = db.query<std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<double>>(
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Employees e "
        "LEFT JOIN Departments d ON e.department_id = d.department_id;");

    for (const auto& r : rows) {
      analysis.left_join_results.push_back(row_to_join_result(r));
    }
  }

  // RIGHT JOIN: all departments (even without employees)
  // SQLite has no native RIGHT JOIN; emulate by swapping tables
  // and doing a LEFT JOIN from Departments to Employees.
  {
    const auto rows = db.query<std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<double>>(
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Departments d "
        "LEFT JOIN Employees e ON d.department_id = e.department_id;");

    for (const auto& r : rows) {
      analysis.right_join_results.push_back(row_to_join_result(r));
    }
  }

  // FULL JOIN: include all employees and all departments.
  //
  // SQLite does not support FULL OUTER JOIN directly, so we emulate it
  // as UNION of:
  //  - LEFT JOIN (Departments -> Employees)
  //  - LEFT JOIN (Employees -> Departments) where the join failed (d.department_name IS NULL)
  {
    const auto rows = db.query<std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<std::string>,
                               std::optional<double>>(
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Departments d "
        "LEFT JOIN Employees e ON d.department_id = e.department_id "
        "UNION "
        "SELECT d2.department_name, e2.first_name, e2.last_name, e2.salary "
        "FROM Employees e2 "
        "LEFT JOIN Departments d2 ON e2.department_id = d2.department_id "
        "WHERE d2.department_name IS NULL;");

    for (const auto& r : rows) {
      analysis.full_join_results.push_back(row_to_join_result(r));
    }
  }

  return analysis;
}

}  // namespace analyze_department_employees
