 */
inline std::string in_operator_usage() {
  using sqlgen::in;
  using sqlgen::select_from;
  using sqlgen::where;

  // Open SQLite connection to "test_db.sqlite"
  sqlgen::sqlite::Connection conn{"test_db.sqlite"};

  // Build the query:
  // SELECT * FROM Status WHERE code IN (1, 2, 3);
  auto stmt = select_from<Status>()(
      where(in(&Status::code, std::vector<int>{1, 2, 3}))
  );

  // Execute the query and obtain the results as a vector of Status
  auto result = conn.read<Status>(stmt);
  if (!result.ok()) {
    // On error, return the error message.
    return result.error();
  }

  const auto& statuses = result.value();

  // Return a summary string that confirms how many records were fetched.
  // (The instructions ask to "return the query results as a list of Status
  // records", but this function is specified to return std::string; here we
  // just report the count as a simple textual representation.)
  return "Fetched " + std::to_string(statuses.size()) + " Status record(s).";
}

}  // namespace in_operator_usage
