#include <string>

namespace aggregation_arithmetic {

struct Product {
  sqlgen::PrimaryKey<int> id;
  double price;
};

/**
 * This function demonstrates arithmetic on aggregations.
 * Returns: double.
 */
inline double aggregation_arithmetic() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // Connection failed; in a real application you might throw or handle this.
    // For this example, return 0.0 on failure.
    return 0.0;
  }
  auto conn = *conn_res;

  // Build an aggregation expression for the average price and add 10
  // avg(price) + 10
  auto avg_price_expr = sqlgen::avg(&Product::price) + 10.0;

  // Select the aggregated value from the Product table
  using namespace sqlgen;
  auto stmt = select_from<Product>(avg_price_expr);

  auto exec_res = sqlgen::exec(conn, stmt);
  if (!exec_res || exec_res->empty()) {
    // No result (e.g., empty table). Return just 10 in that case,
    // since avg(NULL) is effectively NULL/absent.
    return 10.0;
  }

  // exec_res->front() should contain a single double element
  const auto& row = exec_res->front();
  if (row.empty()) {
    return 10.0;
  }

  // The first (and only) column is our computed value.
  return std::get<double>(row[0]);
}

}  // namespace aggregation_arithmetic
