inline std::vector<NicknameResult> coalesce_function() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // On failure just return an empty result (tests will typically assert on SQL,
    // not on runtime errors).
    return {};
  }
  auto conn = std::move(conn_res.value());

  // Build a query that selects COALESCE(nickname, 'Anonymous') AS display_name
  // from the Profile table, mapping into NicknameResult.
  //
  // We use the "select" pipeline with a string SQL expression for the column
