  auto stmt =
      sqlgen::read<std::vector<NicknameResult>> |
      sqlgen::select("COALESCE(nickname, 'Anonymous') AS display_name") |
      sqlgen::from<Profile>();

  // Execute the query and return the resulting vector<NicknameResult>.
  auto result = conn->execute(stmt);

  if (!result) {
    return {};
  }
  return std::move(result.value());
}

