#pragma once

#include <algorithm>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * @param limit_count The number of top products to retrieve. Default is 10.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Open SQLite connection
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return {};
  }
  auto conn = *conn_res;

  // Build query:
  // SELECT p.product_id, p.product_name, p.category,
  //        SUM(p.price * s.quantity) AS total_sales
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT N;

  auto query =
      sqlgen::read<std::vector<TopProduct>> |
      sqlgen::select(
          "Product.product_id"_c,
          "Product.product_name"_c,
          "Product.category"_c,
          sum("Product.price"_c * "Sales.quantity"_c).as("total_sales")) |
      sqlgen::from<Product>() |
      sqlgen::inner_join<Sales>(
          on("Product.product_id"_c == "Sales.product_id"_c)) |
      sqlgen::group_by("Product.product_id"_c,
                       "Product.product_name"_c,
                       "Product.category"_c) |
      sqlgen::order_by(desc(col("total_sales"))) |
      sqlgen::limit(static_cast<int>(limit_count));

  auto res = conn->read(query);
  if (!res) {
    return {};
  }

  return *res;
}

}  // namespace get_top_products
