```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <unordered_map>

namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

/**
 * @brief Update inventory stock based on a shipment.
 * @param received A map of {product_id, quantity_received}.
 * @return true If all updates are successful, false otherwise.
 */
bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }

  // Ensure the Product table exists
  auto tbl_res = create_table<Product>(conn_res);
  if (!tbl_res) {
    return false;
  }

  // Begin a single transaction
  auto txn_res = begin_transaction(conn_res.value());
  if (!txn_res) {
    return false;
  }
  auto txn = txn_res.value();

  // Chain all updates onto the transaction result
  auto res = Result<Ref<decltype(txn)>>{txn};

  for (const auto& [pid, qty] : received) {
    // Build: UPDATE Product SET stock = stock + qty WHERE product_id = pid;
    res = res.and_then([&](const auto& c) {
      const auto sets =
          "stock"_c.set("stock"_c + qty);  // stock = stock + qty
      const auto condition = "product_id"_c == pid;
      // Use sqlgen::update with a WHERE clause
      const auto q = update<Product>(sets) | where(condition);
      return q(c);
    });

    if (!res) {
      // On any failure, roll back and return false
      auto _ = rollback(txn);
      (void)_;
      return false;
    }
  }

  // Commit the transaction if all updates succeeded
  auto commit_res = commit(txn);
  return commit_res.has_value();
}

}  // namespace update_inventory_stock
```

