```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace create_view_order_summary {

struct Order {
  static constexpr const char* tablename = "Order";

  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  static constexpr const char* tablename = "OrderItem";

  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* viewname = "OrderSummaryView";
  static constexpr bool is_view = true;

  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: Create a view `OrderSummaryView` that shows order ID, customer name, and (unit_price * quantity) as total price for each order.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // On error, return empty vector (could also throw, but tests typically expect no throw)
    return {};
  }
  auto conn = *conn_result;

  // Build the query that computes the order summary
  // SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) AS total
  // FROM Order o INNER JOIN OrderItem oi ON o.order_id = oi.order_id
  // GROUP BY o.order_id, o.customer;
  auto summary_query =
      select_from<Order, OrderItem>(
          "order_id"_c, "customer"_c,
          ("unit_price"_c * "quantity"_c).sum().as("total"))
          .where("Order.order_id"_c == "OrderItem.order_id"_c)
          .group_by("Order.order_id"_c, "Order.customer"_c);

  // Create the view OrderSummaryView if it does not exist
  auto create_view_stmt = create_as<OrderSummary>(summary_query) | if_not_exists;

  if (!conn->execute(create_view_stmt)) {
    return {};
  }

  // Read from the view OrderSummaryView
  auto read_result = conn->read<OrderSummary>();
  if (!read_result) {
    return {};
  }

  return *read_result;
}

}  // namespace create_view_order_summary
