```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace left_join_explicit {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> id;
  int user_id;
  std::string title;
};

struct Product {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

/**
 * This function demonstrates LIKE usage.
 * Returns: std::vector<Product>.
 */
inline std::vector<Product> like_pattern_matching() {
  // Open a connection to the SQLite database "test_db.sqlite".
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // Build a query selecting Product rows where name LIKE 'A%'.
  using namespace sqlgen;

  auto query =
      select<Product>()
          .from<Product>()
          .where(column<&Product::name>() % "A%");

  // Execute the query and collect all results into a std::vector<Product>.
  return conn.collect<Product>(query);
}

}  // namespace left_join_explicit
