```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  // Connect to the SQLite database "test_db.sqlite"
  Connection conn("test_db.sqlite");

  // We'll compute weekday (0–6) via SQLite's strftime('%w', sale_date)
  // and sum quantities grouped by that weekday.
  //
  // Since the sqlgen high-level query builders for custom expressions
  // (like strftime) are not visible in the provided snippets, we can
  // use a small dynamic SQL statement that maps directly into our
  // WeekdayStats struct via the iterator interface.

  // Build a dynamic SELECT statement:
  // SELECT CAST(strftime('%w', sale_date) AS INTEGER) AS weekday,
  //        SUM(quantity) AS total_quantity
  // FROM Sales
  // GROUP BY CAST(strftime('%w', sale_date) AS INTEGER);
  sqlgen::dynamic::Statement stmt;

  // Table reference
  sqlgen::dynamic::Table sales_table;
  sales_table.name = "Sales";
  stmt.select.from = sales_table;

  // Expression: CAST(strftime('%w', sale_date) AS INTEGER) AS weekday
  sqlgen::dynamic::Column weekday_expr;
  weekday_expr.table = sales_table;
  weekday_expr.name = "weekday";
  weekday_expr.expr = "CAST(strftime('%w', sale_date) AS INTEGER)";

  // Expression: SUM(quantity) AS total_quantity
  sqlgen::dynamic::Column sum_quantity_expr;
  sum_quantity_expr.table = sales_table;
  sum_quantity_expr.name = "total_quantity";
  sum_quantity_expr.expr = "SUM(quantity)";

  stmt.select.columns.push_back(weekday_expr);
  stmt.select.columns.push_back(sum_quantity_expr);

  // GROUP BY weekday expression
  sqlgen::dynamic::GroupBy gb;
  gb.columns.push_back(weekday_expr);
  stmt.select.group_by = gb;

  // Execute statement using sqlite-specific to_sql and iterator
  const auto sql = sqlgen::sqlite::to_sql(stmt);
  auto it_result = conn.exec(sql);

  std::vector<WeekdayStats> result;

  if (!it_result) {
    // In case of error, return empty result
    return result;
  }

  auto it = *it_result;
  for (; it; ++it) {
    WeekdayStats ws{};
    // Columns are: 0 -> weekday, 1 -> total_quantity
    ws.weekday = it.get<int>(0).value_or(0);
    ws.total_quantity = it.get<int>(1).value_or(0);
    result.push_back(ws);
  }

  return result;
}

}  // namespace weekday_sales_analysis
```

