```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace update_with_arithmetic {

struct Player {
  sqlgen::PrimaryKey<int> id;
  int score;
};

/**
 * This function demonstrates updating a column with arithmetic.
 * Returns: std::vector<Player>.
 */
inline std::vector<Player> update_with_arithmetic() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // On failure, return an empty vector (or handle error as appropriate).
    return {};
  }
  auto conn = *conn_result;

  // Construct and execute:
  //   UPDATE Player SET score = score + 10;
  //
  // Then read back all rows from Player.
  //
  // `update<Player>` builds an UPDATE statement. For arithmetic we use the
  // column itself as the "value": score = score + 10 is represented as
  // `score = score + 10` in SQL; with sqlgen we can use `score = score + 10`
  // via the column plus a literal value.
  const auto update_query =
      update<Player>("score"_c.set("score"_c + 10));

  // Execute the UPDATE.
  auto upd_res = conn.exec(update_query);
  if (!upd_res) {
    return {};
  }

  // Read all updated rows.
  auto read_res = conn.and_then(read<std::vector<Player>>);
  if (!read_res) {
    return {};
  }

  return *read_res;
}

}  // namespace update_with_arithmetic
