  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using sqlgen::col;
  using sqlgen::dynamic::Statement;

  // Open SQLite connection to the given database.
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // Build SQL statement using SQLite date/time functions.
  // SQLite doesn't have DAY/MONTH/YEAR/HOUR/MINUTE/SECOND/DAYS_BETWEEN,
  // so we use strftime and julianday equivalents.
  const Statement stmt =
      sqlgen::select(
          col<Project>("project_id"),
          col<Project>("name"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%d', t.start_time) AS INTEGER)"),
                     "day"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%m', t.start_time) AS INTEGER)"),
                     "month"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%Y', t.start_time) AS INTEGER)"),
                     "year"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%H', t.start_time) AS INTEGER)"),
                     "hour"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%M', t.start_time) AS INTEGER)"),
                     "minute"),
          sqlgen::as(sqlgen::raw("CAST(strftime('%S', t.start_time) AS INTEGER)"),
                     "second"),
          sqlgen::as(
              sqlgen::raw(
                  "julianday(t.end_time) - julianday(t.start_time)"),
              "duration_days"))
          .from<Project>("Project")
          .inner_join<TimeLog>("TimeLog t",
                               "Project.project_id = t.project_id");

  // Execute the query and collect the results.
  auto res = conn.select<TimeMetrics>(stmt);

  if (!res.ok()) {
    // On error, return an empty vector. In a real application, you might
    // prefer to throw or log the error.
    return {};
  }

  return res.value();
}

}  // namespace project_time_tracking
