output.text:
```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Define the query:
  // SELECT User.user_id, User.name,
  //        COUNT(Post.post_id) AS post_count,
  //        AVG(LENGTH(Post.content)) AS avg_length
  // FROM User
  // LEFT JOIN Post ON User.user_id = Post.user_id
  // GROUP BY User.user_id, User.name;
  //
  // Then map the result into Stats.
  const auto get_stats =
      select_from<User, Post>(
          "User.user_id"_c, "User.name"_c,
          count("Post.post_id"_c).as<"post_count">(),
          avg(length("Post.content"_c)).as<"avg_length">()) |
      left_join_on<User, Post>("User.user_id"_c == "Post.user_id"_c) |
      group_by("User.user_id"_c, "User.name"_c) |
      to<Stats>;

  // Connect to the SQLite database and execute the query.
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();
  return conn.and_then(get_stats).value();
}

}  // namespace group_by_with_aggregations
```

