#include <sqlgen/transpilation/read_to_select_from.hpp>
#include <string>
#include <vector>

namespace read_to_select_from_usage {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
  int age;
};

/**
 * Constructs a query selecting all columns from `User` where age is greater than 18 with a limit of 10.
 * Returns: std::vector<User>.
 */
inline std::vector<User> read_to_select_from_usage() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // If connection fails, return an empty result.
    return {};
  }
  auto conn = conn_res.value();

  // Build the WHERE clause: age > 18
  const auto where_clause = where("age"_c > 18);

  // Build the LIMIT clause: LIMIT 10
  const auto limit_clause = limit(10);

  // Transpile the read to a dynamic SelectFrom query.
  const auto select_from_stmt =
      sqlgen::transpilation::read_to_select_from<User>(where_clause,
                                                       limit_clause);

  // Execute the query and read the results into std::vector<User>.
  auto res = conn->read<std::vector<User>>(select_from_stmt);
  if (!res) {
    return {};
  }

  return res.value();
}

}  // namespace read_to_select_from_usage
