```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace create_table_as_select {

struct Source {
  sqlgen::PrimaryKey<int> id;
  int value;
};

struct Target {
  int value;
};

/**
 * Description: This function creates a table `Target` from a select query on `Source` 
 * Returns: std::vector<Target>.
 */
inline std::vector<Target> create_table_as_select() {
  using namespace sqlgen;

  // Connect to the SQLite database `test_db.sqlite`
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // In a real application you might throw or handle the error differently.
    // Here we just return an empty result on failure.
    return {};
  }
  auto conn = std::move(conn_res.value());

  // Ensure the Source table exists (based on the struct Source)
  const auto create_source_stmt = transpilation::to_create_table<Source>();
  conn->execute(create_source_stmt);

  // Build: CREATE TABLE "Target" AS SELECT "value" FROM "Source" WHERE "value" > 100;
  sqlite::dynamic::CreateAs create_as;
  create_as.what = sqlite::dynamic::TableOrView::table;
  create_as.table_or_view = sqlite::dynamic::Table{.name = "Target"};
  create_as.or_replace = false;
  create_as.if_not_exists = false;

  // Build the SELECT part
  sqlite::dynamic::SelectFrom select{
      .table = sqlite::dynamic::Table{.name = "Source"},
      .columns = {sqlite::dynamic::Column{.name = "value"}}};

  // WHERE "value" > 100
  sqlite::dynamic::Expression where_expr;
  where_expr.op = sqlite::dynamic::BinaryOp::gt;
  where_expr.left = sqlite::dynamic::Operand{sqlite::dynamic::Column{.name = "value"}};
  where_expr.right =
      sqlite::dynamic::Operand{sqlite::dynamic::Literal{.value = "100"}};
  select.where = where_expr;

  create_as.query = select;

  // Execute CREATE TABLE AS SELECT ...
  conn->execute(create_as);

  // Read back all rows from Target into std::vector<Target>
  const auto select_target_stmt =
      transpilation::read_to_select_from<Target>();
  auto rows_res = conn->read<Target>(select_target_stmt);
  if (!rows_res) {
    return {};
  }
  return rows_res.value();
}

}  // namespace create_table_as_select
